-- HQ-managed shared library. Immutable storage keys protect programme and billing identity.
CREATE TABLE public.scl293_themes(id text PRIMARY KEY, storage_key text UNIQUE NOT NULL, data jsonb NOT NULL, revision bigint NOT NULL DEFAULT 1, updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE public.scl293_programs(id text PRIMARY KEY, data jsonb NOT NULL, revision bigint NOT NULL DEFAULT 1, updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE public.scl293_media_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),theme_id text NOT NULL REFERENCES public.scl293_themes(id),orientation text NOT NULL CHECK(orientation IN ('vertical','horizontal')),previous_file text NOT NULL,new_file text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE public.scl293_themes ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.scl293_programs ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.scl293_media_events ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.scl293_themes,public.scl293_programs,public.scl293_media_events FROM PUBLIC,anon,authenticated;

CREATE FUNCTION public.scl293_library(p_token text DEFAULT NULL,p_hq_key text DEFAULT NULL) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE hq boolean:=nullif(p_hq_key,'') IS NOT NULL;
BEGIN
 IF hq THEN PERFORM public.scl290_assert_hq(p_hq_key);ELSE PERFORM public.scl290_token_id(p_token);END IF;
 RETURN jsonb_build_object('themes',(SELECT coalesce(jsonb_agg(data||jsonb_build_object('revision',revision) ORDER BY data->>'title'),'[]') FROM public.scl293_themes WHERE hq OR data->>'status'<>'draft'),
 'programs',(SELECT coalesce(jsonb_agg(data||jsonb_build_object('revision',revision) ORDER BY data->>'title'),'[]') FROM public.scl293_programs WHERE hq OR data->>'status'<>'draft'),
 'media_events',CASE WHEN hq THEN (SELECT coalesce(jsonb_agg(to_jsonb(e) ORDER BY e.created_at),'[]') FROM public.scl293_media_events e) ELSE '[]'::jsonb END);
END $$;

CREATE FUNCTION public.scl293_save(p_hq_key text,p_kind text,p_id text,p_revision bigint,p_data jsonb,p_media_mode text DEFAULT 'correction') RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE old jsonb; rev bigint; d jsonb; item jsonb; v jsonb; n text; fmt text; key text;
BEGIN
 PERFORM public.scl290_assert_hq(p_hq_key);
 IF p_kind NOT IN ('theme','program') OR p_id IS NULL OR length(p_id)>100 THEN RAISE EXCEPTION 'Μη έγκυρη εγγραφή';END IF;
 IF jsonb_typeof(p_data)<>'object' OR nullif(btrim(p_data->>'title'),'') IS NULL THEN RAISE EXCEPTION 'Συμπληρώστε τίτλο';END IF;
 IF coalesce(p_data->>'status','') NOT IN ('draft','available','withdrawn') THEN RAISE EXCEPTION 'Μη έγκυρη κατάσταση';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(p_kind||p_id,293));
 IF p_kind='theme' THEN
  SELECT data,revision,storage_key INTO old,rev,key FROM public.scl293_themes WHERE id=p_id FOR UPDATE;
 ELSE SELECT data,revision INTO old,rev FROM public.scl293_programs WHERE id=p_id FOR UPDATE;END IF;
 IF coalesce(rev,0)<>p_revision THEN RAISE EXCEPTION 'Η εγγραφή άλλαξε από άλλον χρήστη. Ανανεώστε τη βιβλιοθήκη.';END IF;
 d:=(p_data-'revision'-'replacementFormats')||jsonb_build_object('id',p_id,'title',btrim(p_data->>'title'));
 IF p_kind='theme' THEN
  IF old->>'status' IN ('available','withdrawn') AND d->>'status'='draft' THEN RAISE EXCEPTION 'Χρησιμοποιήστε απόσυρση για υπάρχουσα θεματική'; END IF;
  key:=coalesce(key,'library:'||p_id);
  d:=d||jsonb_build_object('key',key,'legacySlots',coalesce(old->'legacySlots','[]'::jsonb),'aliases',coalesce(old->'aliases','[]'::jsonb)||CASE WHEN old IS NOT NULL AND old->>'title'<>d->>'title' THEN jsonb_build_array(old->>'title') ELSE '[]'::jsonb END);
  IF jsonb_typeof(d->'variants') IS DISTINCT FROM 'array' OR jsonb_array_length(d->'variants')=0 THEN RAISE EXCEPTION 'Λείπουν τα στησίματα';END IF;
  FOR item IN SELECT value FROM jsonb_array_elements(coalesce(old->'variants','[]')) LOOP
   IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(d->'variants') x WHERE x->>'id'=item->>'id') THEN RAISE EXCEPTION 'Τα υπάρχοντα στησίματα πρέπει να διατηρηθούν';END IF;
  END LOOP;
  FOR v IN SELECT value FROM jsonb_array_elements(d->'variants') LOOP
   FOREACH n IN ARRAY ARRAY['Στήσιμο Μάρκας','Υβριδικό Στήσιμο','Μικτό Στήσιμο'] LOOP
    IF jsonb_typeof(v->'setups'->n) IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'Διατηρούνται και οι τρεις τρόποι στησίματος';END IF;
    IF jsonb_typeof(v->'setups'->n->'products') IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'Μη έγκυρα προϊόντα';END IF;
    IF (v->'setups'->n)?'shelves' AND (jsonb_typeof(v->'setups'->n->'shelves')<>'array' OR jsonb_array_length(v->'setups'->n->'shelves')<>4) THEN RAISE EXCEPTION 'Απαιτούνται τέσσερα ράφια';END IF;
   END LOOP;
  END LOOP;
  IF p_media_mode NOT IN ('correction','replacement') THEN RAISE EXCEPTION 'Επιλέξτε διόρθωση ονομασίας ή νέο υλικό';END IF;
  INSERT INTO public.scl293_themes(id,storage_key,data) VALUES(p_id,key,d) ON CONFLICT(id) DO UPDATE SET data=excluded.data,revision=scl293_themes.revision+1,updated_at=now();
  IF old IS NOT NULL AND p_media_mode='replacement' THEN
   FOREACH fmt IN ARRAY ARRAY['vertical','horizontal'] LOOP
    IF (p_data->'replacementFormats') ? fmt THEN
     IF nullif(d->'files'->>fmt,'') IS NULL THEN RAISE EXCEPTION 'Συμπληρώστε όνομα αρχείου για το νέο υλικό'; END IF;
     INSERT INTO public.scl293_media_events(theme_id,orientation,previous_file,new_file) VALUES(p_id,fmt,coalesce(old->'files'->>fmt,''),d->'files'->>fmt);
    END IF;
   END LOOP;
  END IF;
 ELSE
  IF jsonb_typeof(d->'months') IS DISTINCT FROM 'array' OR jsonb_array_length(d->'months')<>12 THEN RAISE EXCEPTION 'Το πρόγραμμα χρειάζεται 12 μήνες';END IF;
  FOR item IN SELECT value FROM jsonb_array_elements(d->'months') LOOP
   IF d->>'status'='available' AND NOT EXISTS(SELECT 1 FROM public.scl293_themes t WHERE t.id=item->>'theme' AND t.data->>'status'='available' AND EXISTS(SELECT 1 FROM jsonb_array_elements(t.data->'variants') x WHERE x->>'id'=item->>'variant')) THEN RAISE EXCEPTION 'Συμπληρώστε και τους 12 μήνες με διαθέσιμες θεματικές';END IF;
  END LOOP;
  INSERT INTO public.scl293_programs(id,data) VALUES(p_id,d) ON CONFLICT(id) DO UPDATE SET data=excluded.data,revision=scl293_programs.revision+1,updated_at=now();
 END IF;
 RETURN d||jsonb_build_object('revision',coalesce(rev,0)+1);
END $$;

CREATE FUNCTION public.scl293_usage(p_hq_key text,p_theme_id text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE k text;
BEGIN
 PERFORM public.scl290_assert_hq(p_hq_key);
 SELECT storage_key INTO k FROM public.scl293_themes WHERE id=p_theme_id;
 RETURN (WITH states AS (
 SELECT pharmacy_id,year,state_json FROM public.scl290_snapshots
 UNION ALL SELECT p.pharmacy_id,p.year,p.state_json FROM public.pharmacy_state p WHERE NOT EXISTS(SELECT 1 FROM public.scl290_snapshots s WHERE s.pharmacy_id=p.pharmacy_id AND s.year=p.year)
 ), usages AS (
 SELECT s.pharmacy_id,p.name,s.year,c->>'title' AS position,c->>'id' AS position_id,m AS month
 FROM states s JOIN public.pharmacies p ON p.id=s.pharmacy_id CROSS JOIN LATERAL jsonb_array_elements(coalesce(s.state_json->'cards','[]')) c CROSS JOIN generate_series(0,11) m
 WHERE c->>'initialPlanLocked'='true' AND (c->'basicSchedule'->>m=k OR c->'simpleSchedule'->>m=k)
 ) SELECT coalesce(jsonb_agg(to_jsonb(u) ORDER BY name,year,month),'[]') FROM usages u);
END $$;
REVOKE ALL ON FUNCTION public.scl293_library(text,text),public.scl293_save(text,text,text,bigint,jsonb,text),public.scl293_usage(text,text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.scl293_library(text,text),public.scl293_save(text,text,text,bigint,jsonb,text),public.scl293_usage(text,text) TO anon,authenticated;

